// Пути округлены до 0.01 pt.

extension IconPart {
    func moved(_ dx: CGFloat, _ dy: CGFloat) -> IconPart {
        var p = self
        p.translate = CGSize(width: translate.width + dx, height: translate.height + dy)
        return p
    }
}

